namespace Sace.Api.Tests;

public class Sprint5RiskMathTests {
  [Fact] public void Independent_factors_are_added(){var rows=RiskScoringMath.Apply([Candidate("A",10),Candidate("B",20),Candidate("C",30)],new Dictionary<RiskCategory,decimal>());Assert.Equal(60,rows.Sum(x=>x.Points));}
  [Fact] public void Max_correlation_prevents_double_counting(){var rows=RiskScoringMath.Apply([Candidate("A",20,"VALUE",RiskCorrelationMode.MAX),Candidate("B",30,"VALUE",RiskCorrelationMode.MAX)],new Dictionary<RiskCategory,decimal>());Assert.Single(rows);Assert.Equal(30,rows.Sum(x=>x.Points));}
  [Fact] public void Category_cap_is_enforced(){var candidates=Enumerable.Range(1,10).Select(x=>Candidate($"M{x}",10)).ToList();var rows=RiskScoringMath.Apply(candidates,new Dictionary<RiskCategory,decimal>{{RiskCategory.VALUATION,30}});Assert.Equal(30,rows.Sum(x=>x.Points));}
  [Fact] public void Negative_weights_never_reduce_score(){var rows=RiskScoringMath.Apply([Candidate("A",-10)],new Dictionary<RiskCategory,decimal>());Assert.Empty(rows);}
  [Fact] public void Per_factor_maximum_is_enforced(){var definition=new RiskFactorDefinition{Code="A",Name="A",Category=RiskCategory.VALUATION,SourceType=RiskSourceType.VALUATION,Weight=50,MaxPoints=12};var rows=RiskScoringMath.Apply([new(definition,"Test",Guid.NewGuid(),"MISMATCH","A","A")],new Dictionary<RiskCategory,decimal>());Assert.Equal(12,Assert.Single(rows).Points);}
  static RiskCandidate Candidate(string code,decimal points,string? correlation=null,RiskCorrelationMode mode=RiskCorrelationMode.SUM){var definition=new RiskFactorDefinition{Code=code,Name=code,Category=RiskCategory.VALUATION,SourceType=RiskSourceType.VALUATION,Weight=points,MaxPoints=points,CorrelationKey=correlation,CorrelationMode=mode};return new(definition,"Test",Guid.NewGuid(),"MISMATCH",code,code,correlation);}
}

public class Sprint5RiskServiceTests {
  [Fact] public async Task Score_is_versioned_explained_and_does_not_mutate_legal(){await using var f=await RiskFixture.Create(30);var result=await f.Service.CalculateAsync(f.Operation.Id,null,f.User.Id);Assert.Equal(30,result.NormalizedScore);Assert.Equal(RiskLevel.MEDIUM,result.RiskLevel);Assert.Single(result.Factors);Assert.Contains("+30",result.Explanation);Assert.Equal(LegalOutcome.NON_COMPLIANT,(await f.Db.AuditResults.SingleAsync()).Outcome);var second=await f.Service.CalculateAsync(f.Operation.Id,null,f.User.Id);Assert.Equal(2,second.Version);}
  [Fact] public async Task Score_is_normalized_to_one_hundred(){await using var f=await RiskFixture.Create(145);var result=await f.Service.CalculateAsync(f.Operation.Id,null,f.User.Id);Assert.Equal(100,result.NormalizedScore);Assert.Equal(RiskLevel.CRITICAL,result.RiskLevel);}
  [Fact] public async Task High_score_creates_only_one_open_review_item(){await using var f=await RiskFixture.Create(80);await f.Service.CalculateAsync(f.Operation.Id,null,f.User.Id);await f.Service.CalculateAsync(f.Operation.Id,null,f.User.Id);Assert.Equal(1,await f.Db.ReviewQueueItems.CountAsync());Assert.Equal(2,await f.Db.OperationRiskScores.CountAsync());}
  [Fact] public async Task Demo_results_and_draft_rrna_factors_are_excluded(){await using var f=await RiskFixture.Create(null);f.AddFactor("DOC",RiskCategory.DOCUMENTATION,RiskSourceType.DOCUMENTATION,"MISSING",10);f.AddFactor("CROSS",RiskCategory.CROSS_VALIDATION,RiskSourceType.CROSS_VALIDATION,"MISMATCH",10);f.AddFactor("RRNA",RiskCategory.RRNA,RiskSourceType.RRNA,"MISSING_EVIDENCE",20);var technical=new Audit{Number="D",TradeOperation=f.Operation,AuditType=AuditType.Daily,Status=AuditStatus.Completed,CreatedBy=f.User.Id};f.Db.AuditResults.Add(new(){Audit=technical,RuleId="DEMO-MISSING",Status=ResultStatus.Missing,Message="Demo"});var crossRule=new CrossValidationRule{Code="DEMO-CROSS",Name="Demo",Description="Demo",SourceDocumentTypeCode="A",SourceFieldCode="A",TargetDocumentTypeCode="B",TargetFieldCode="B"};f.Db.CrossValidationResults.Add(new(){TradeOperation=f.Operation,CrossValidationRule=crossRule,RuleCode=crossRule.Code,RuleVersion=1,Outcome=CrossValidationOutcome.MISMATCH,Explanation="Demo mismatch"});var rule=new RegulatoryRequirement{Code="DRAFT-R",Version=1,Name="Draft",Description="Draft",Status=RegulatoryRequirementStatus.DRAFT};f.Db.RegulatoryRequirementEvaluations.Add(new(){TradeOperation=f.Operation,RegulatoryRequirement=rule,RequirementCode=rule.Code,RequirementVersion=1,AutomatedOutcome=RegulatoryApplicabilityOutcome.APPLIES,EvidenceStatus=RegulatoryEvidenceStatus.MISSING_EVIDENCE,Explanation="Draft",SnapshotJson="{}"});await f.Db.SaveChangesAsync();var result=await f.Service.CalculateAsync(f.Operation.Id,null,f.User.Id);Assert.Equal(0,result.NormalizedScore);Assert.Empty(result.Factors);}
  [Fact] public async Task Verified_rrna_missing_evidence_is_included(){await using var f=await RiskFixture.Create(null);f.AddFactor("RRNA",RiskCategory.RRNA,RiskSourceType.RRNA,"MISSING_EVIDENCE",20);var rule=new RegulatoryRequirement{Code="REAL-R",Version=1,Name="Real",Description="Real",Status=RegulatoryRequirementStatus.VERIFIED};f.Db.RegulatoryRequirementEvaluations.Add(new(){TradeOperation=f.Operation,RegulatoryRequirement=rule,RequirementCode=rule.Code,RequirementVersion=1,AutomatedOutcome=RegulatoryApplicabilityOutcome.APPLIES,EvidenceStatus=RegulatoryEvidenceStatus.MISSING_EVIDENCE,Explanation="Missing",SnapshotJson="{}"});await f.Db.SaveChangesAsync();Assert.Equal(20,(await f.Service.CalculateAsync(f.Operation.Id,null,f.User.Id)).NormalizedScore);}
  [Fact] public async Task Manual_priority_survives_recalculation(){await using var f=await RiskFixture.Create(50);var score=await f.Service.CalculateAsync(f.Operation.Id,null,f.User.Id);var item=await f.Db.ReviewQueueItems.SingleAsync();var review=new ReviewQueueService(f.Db);await review.ChangePriorityAsync(item.Id,RiskLevel.CRITICAL,"Prioridad operativa validada",f.User.Id);f.Db.ChangeTracker.Clear();await f.Service.CalculateAsync(f.Operation.Id,null,f.User.Id);var current=await f.Db.ReviewQueueItems.SingleAsync();Assert.Equal(RiskLevel.CRITICAL,current.CurrentPriority);Assert.Equal(RiskLevel.HIGH,current.OriginalPriority);Assert.NotNull(current.PriorityChangedAt);Assert.Equal(score.TradeOperationId,current.TradeOperationId);}
  [Fact] public async Task Review_state_machine_requires_valid_transition_and_close_notes(){await using var f=await RiskFixture.Create(80);await f.Service.CalculateAsync(f.Operation.Id,null,f.User.Id);var item=await f.Db.ReviewQueueItems.SingleAsync();var review=new ReviewQueueService(f.Db);await Assert.ThrowsAsync<InvalidOperationException>(()=>review.ChangeStatusAsync(item.Id,ReviewQueueStatus.RESOLVED,ReviewResolution.CORRECTED,"ok",f.User.Id));await review.AssignAsync(item.Id,f.User.Id,f.User.Id);await review.ChangeStatusAsync(item.Id,ReviewQueueStatus.IN_REVIEW,null,null,f.User.Id);await Assert.ThrowsAsync<InvalidOperationException>(()=>review.ChangeStatusAsync(item.Id,ReviewQueueStatus.RESOLVED,null,null,f.User.Id));var closed=await review.ChangeStatusAsync(item.Id,ReviewQueueStatus.RESOLVED,ReviewResolution.CORRECTED,"Corregido con evidencia",f.User.Id);Assert.Equal(ReviewQueueStatus.RESOLVED,closed.Status);Assert.NotNull(closed.CompletedAt);Assert.Equal(4,await f.Db.ReviewQueueHistory.CountAsync());}
}

public class Sprint5BatchTests {
  [Fact] public async Task Creation_is_a_snapshot_and_later_operations_are_not_added(){await using var f=await BatchFixture.Create();var original=Enumerable.Range(0,5).Select(_=>f.Operation()).ToList();await f.Save();var batch=await f.Service.CreateAsync(new("Snapshot",null,null,null,null,null,null,null,null),f.User.Id);f.Operation();await f.Save();Assert.Equal(5,batch.Operations.Count);Assert.All(original,x=>Assert.Contains(batch.Operations,b=>b.TradeOperationId==x.Id));}
  [Fact] public async Task Batch_continues_after_failure_and_reports_partial_completion(){await using var f=await BatchFixture.Create();var operations=Enumerable.Range(0,10).Select(_=>f.Operation()).ToList();await f.Save();f.Pipeline.Fail.Add(operations[4].Id);var result=await f.Service.ExecuteAsync((await f.Service.CreateAsync(new("Run",null,null,null,null,null,null,null,null),f.User.Id)).Id,f.User.Id);Assert.Equal(BatchAuditStatus.COMPLETED_WITH_ERRORS,result.Status);Assert.Equal(10,result.ProcessedOperations);Assert.Equal(9,result.SuccessfulOperations);Assert.Equal(1,result.FailedOperations);Assert.Equal(10,f.Pipeline.Calls.Count);}
  [Fact] public async Task Retry_processes_only_failed_operations(){await using var f=await BatchFixture.Create();var a=f.Operation();var b=f.Operation();await f.Save();f.Pipeline.Fail.Add(b.Id);var batch=await f.Service.CreateAsync(new("Retry",null,null,null,null,null,null,null,null),f.User.Id);await f.Service.ExecuteAsync(batch.Id,f.User.Id);f.Pipeline.Fail.Clear();var callsBeforeA=f.Pipeline.Calls.Count(x=>x==a.Id);var retried=await f.Service.ExecuteAsync(batch.Id,f.User.Id,true);Assert.Equal(callsBeforeA,f.Pipeline.Calls.Count(x=>x==a.Id));Assert.Equal(2,f.Pipeline.Calls.Count(x=>x==b.Id));Assert.Equal(BatchAuditStatus.COMPLETED,retried.Status);}
  [Fact] public async Task Configured_batch_limit_is_enforced(){await using var f=await BatchFixture.Create(max:100);for(var i=0;i<101;i++)f.Operation();await f.Save();var error=await Assert.ThrowsAsync<InvalidOperationException>(()=>f.Service.CreateAsync(new("Too many",null,null,null,null,null,null,null,null),f.User.Id));Assert.Equal("BATCH_TOO_LARGE",error.Message);}
  [Fact] public async Task Cancellation_preserves_completed_work_and_stops_pending_items(){await using var f=await BatchFixture.Create();f.Operation();f.Operation();f.Operation();await f.Save();var batch=await f.Service.CreateAsync(new("Cancel",null,null,null,null,null,null,null,null),f.User.Id);f.Pipeline.AfterFirst=async()=>{var tracked=await f.Db.BatchAudits.FindAsync(batch.Id);tracked!.Status=BatchAuditStatus.CANCELLED;await f.Db.SaveChangesAsync();};var result=await f.Service.ExecuteAsync(batch.Id,f.User.Id);Assert.Equal(BatchAuditStatus.CANCELLED,result.Status);Assert.Equal(1,result.SuccessfulOperations);Assert.Equal(2,result.Operations.Count(x=>x.Status==BatchOperationStatus.CANCELLED));}
}

public class Sprint5DashboardTests {
  [Fact] public async Task Dashboard_distribution_matches_latest_scores(){await using var f=await DashboardFixture.Create();var dashboard=await f.Service.GetAsync(1,20,"riskScore","desc");Assert.Equal(10,dashboard.TotalOperations);Assert.Equal(3,dashboard.Distribution.Single(x=>x.Level==RiskLevel.LOW).Count);Assert.Equal(2,dashboard.Distribution.Single(x=>x.Level==RiskLevel.MEDIUM).Count);Assert.Equal(4,dashboard.Distribution.Single(x=>x.Level==RiskLevel.HIGH).Count);Assert.Equal(1,dashboard.Distribution.Single(x=>x.Level==RiskLevel.CRITICAL).Count);}
  [Fact] public async Task Dashboard_counts_operation_once_and_uses_latest_score(){await using var f=await DashboardFixture.Create();var dashboard=await f.Service.GetAsync(1,20,"riskScore","desc");Assert.Equal(10,dashboard.TotalRows);Assert.Equal(10,dashboard.Operations.Count);var operation=dashboard.Operations.Single(x=>x.OperationId==f.VersionedOperationId);Assert.Equal(10,operation.Score);Assert.Equal(RiskLevel.LOW,operation.Level);}
}

public class Sprint5ApiSecurityTests {
  [Theory]
  [InlineData("GET","/api/batch-audits")][InlineData("POST","/api/batch-audits")][InlineData("GET","/api/batch-audits/00000000-0000-0000-0000-000000000001")][InlineData("POST","/api/batch-audits/00000000-0000-0000-0000-000000000001/start")]
  [InlineData("GET","/api/risk/dashboard")][InlineData("GET","/api/operations/00000000-0000-0000-0000-000000000001/risk")][InlineData("POST","/api/operations/00000000-0000-0000-0000-000000000001/risk/calculate")]
  [InlineData("GET","/api/review-queue")][InlineData("POST","/api/review-queue/00000000-0000-0000-0000-000000000001/priority")]
  public async Task Sprint5_endpoints_require_jwt(string method,string path){using var factory=new SaceFactory();var response=await factory.CreateClient().SendAsync(new HttpRequestMessage(new HttpMethod(method),path));Assert.Equal(HttpStatusCode.Unauthorized,response.StatusCode);}
  [Fact] public async Task Seed_contains_one_active_versioned_risk_profile(){using var factory=new SaceFactory();_ = factory.CreateClient();await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<SaceDbContext>();var profile=Assert.Single(await db.RiskProfiles.Include(x=>x.Factors).Where(x=>x.Code=="RISK-OPS-V1").ToListAsync());Assert.Equal(RiskProfileStatus.ACTIVE,profile.Status);Assert.Equal(1,profile.Version);Assert.Equal(10,profile.Factors.Count);}
}

public class Sprint5MigrationTests {
  private const string Previous="20261022195429_OfficialRegulatoryCatalogV1";
  [Fact] public async Task Incremental_and_down_migration_preserve_existing_data(){var directory=Path.Combine(Path.GetTempPath(),$"sace-sprint5-{Guid.NewGuid():N}");Directory.CreateDirectory(directory);var path=Path.Combine(directory,"test.db");try{Guid operationId,legalResultId;await using(var db=Context(path)){var migrator=db.Database.GetService<IMigrator>();await migrator.MigrateAsync(Previous);var user=new User{Name="Migration",Email="sprint5@example.invalid",PasswordHash="x"};var op=new TradeOperation{Folio="KEEP-S5",PedimentoNumber="26",Period="2026-10",OperationDate=new(2026,10,1),TariffFraction="1"};var audit=new Audit{Number="LEGAL-S5",TradeOperation=op,AuditType=AuditType.Legal,Status=AuditStatus.Completed,CreatedBy=user.Id};var legal=new AuditResult{Audit=audit,RuleId="LEGAL-S5",Status=ResultStatus.Valid,Outcome=LegalOutcome.COMPLIANT,IsIncludedInLegalCompliance=true,Message="Preserve"};db.AddRange(user,op,audit,legal);await db.SaveChangesAsync();operationId=op.Id;legalResultId=legal.Id;await migrator.MigrateAsync();Assert.True(await Table(db,"BatchAudits"));Assert.True(await Table(db,"OperationRiskScores"));Assert.True(await Table(db,"ReviewQueueItems"));await migrator.MigrateAsync(Previous);}await using(var db=Context(path)){Assert.False(await Table(db,"BatchAudits"));Assert.True(await db.TradeOperations.AnyAsync(x=>x.Id==operationId));Assert.Equal(LegalOutcome.COMPLIANT,(await db.AuditResults.SingleAsync(x=>x.Id==legalResultId)).Outcome);}}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(directory))Directory.Delete(directory,true);}}
  static SaceDbContext Context(string path)=>new(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite($"Data Source={path}").Options);
  static async Task<bool> Table(SaceDbContext db,string name){var connection=(SqliteConnection)db.Database.GetDbConnection();if(connection.State!=System.Data.ConnectionState.Open)await connection.OpenAsync();await using var command=connection.CreateCommand();command.CommandText="SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name=$name";command.Parameters.AddWithValue("$name",name);return Convert.ToInt64(await command.ExecuteScalarAsync())==1;}
}

sealed class RiskFixture:IAsyncDisposable {
  readonly SqliteConnection connection;public SaceDbContext Db{get;}public User User{get;}public TradeOperation Operation{get;}public RiskProfile Profile{get;}public OperationRiskScoringService Service{get;}
  RiskFixture(SqliteConnection connection,SaceDbContext db,User user,TradeOperation operation,RiskProfile profile){this.connection=connection;Db=db;User=user;Operation=operation;Profile=profile;Service=new(db);}
  public static async Task<RiskFixture>Create(decimal? legalWeight){var connection=new SqliteConnection("DataSource=:memory:");await connection.OpenAsync();var db=new SaceDbContext(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite(connection).Options);await db.Database.EnsureCreatedAsync();var user=new User{Name="Risk",Email=$"{Guid.NewGuid():N}@example.invalid",PasswordHash="x"};var op=new TradeOperation{Folio=$"R-{Guid.NewGuid():N}",PedimentoNumber="26",Period="2026-10",OperationDate=new(2026,10,1),TariffFraction="1"};var profile=new RiskProfile{Code="TEST",Version=1,Name="Test",Description="Test",Status=RiskProfileStatus.ACTIVE,EffectiveFrom=new(2026,1,1),CategoryCapsJson="{}"};db.AddRange(user,op,profile);if(legalWeight.HasValue){profile.Factors.Add(new(){Code="LEGAL",Name="Legal",Category=RiskCategory.LEGAL,SourceType=RiskSourceType.LEGAL,SourceOutcome="NON_COMPLIANT",Weight=legalWeight.Value,MaxPoints=legalWeight.Value,Severity=RiskSeverity.CRITICAL});var audit=new Audit{Number="L",TradeOperation=op,AuditType=AuditType.Legal,Status=AuditStatus.Completed,CreatedBy=user.Id};db.AuditResults.Add(new(){Audit=audit,RuleId="LEGAL-T",Status=ResultStatus.Invalid,Outcome=LegalOutcome.NON_COMPLIANT,IsIncludedInLegalCompliance=true,Message="No conforme"});}await db.SaveChangesAsync();return new(connection,db,user,op,profile);}
  public void AddFactor(string code,RiskCategory category,RiskSourceType source,string outcome,decimal points)=>Db.RiskFactorDefinitions.Add(new(){RiskProfile=Profile,Code=code,Name=code,Category=category,SourceType=source,SourceOutcome=outcome,Weight=points,MaxPoints=points,Severity=RiskSeverity.HIGH});
  public async ValueTask DisposeAsync(){await Db.DisposeAsync();await connection.DisposeAsync();}
}

