sealed class DashboardFixture:IAsyncDisposable {
  readonly SqliteConnection connection;public SaceDbContext Db{get;}public RiskDashboardService Service{get;}public Guid VersionedOperationId{get;}
  DashboardFixture(SqliteConnection connection,SaceDbContext db,RiskDashboardService service,Guid versionedOperationId){this.connection=connection;Db=db;Service=service;VersionedOperationId=versionedOperationId;}
  public static async Task<DashboardFixture>Create(){var connection=new SqliteConnection("DataSource=:memory:");await connection.OpenAsync();var db=new SaceDbContext(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite(connection).Options);await db.Database.EnsureCreatedAsync();var profile=new RiskProfile{Code="DASH",Version=1,Name="Dashboard",Description="Synthetic",Status=RiskProfileStatus.ACTIVE};db.Add(profile);var levels=new[]{RiskLevel.LOW,RiskLevel.LOW,RiskLevel.LOW,RiskLevel.MEDIUM,RiskLevel.MEDIUM,RiskLevel.HIGH,RiskLevel.HIGH,RiskLevel.HIGH,RiskLevel.HIGH,RiskLevel.CRITICAL};Guid versioned=Guid.Empty;for(var i=0;i<levels.Length;i++){var op=new TradeOperation{Folio=$"D-{i}",PedimentoNumber=$"26-{i}",Period="2026-10",OperationDate=new(2026,10,i+1),TariffFraction=i%2==0?"85011010":"85171301",CustomsOffice=i%2==0?"160":"470"};db.Add(op);if(i==0){versioned=op.Id;db.OperationRiskScores.Add(new(){TradeOperation=op,RiskProfile=profile,RiskProfileCode=profile.Code,RiskProfileVersion=1,Version=1,RawScore=90,NormalizedScore=90,RiskLevel=RiskLevel.CRITICAL,Explanation="old"});}var score=levels[i] switch{RiskLevel.LOW=>10,RiskLevel.MEDIUM=>30,RiskLevel.HIGH=>50,_=>80};db.OperationRiskScores.Add(new(){TradeOperation=op,RiskProfile=profile,RiskProfileCode=profile.Code,RiskProfileVersion=1,Version=i==0?2:1,RawScore=score,NormalizedScore=score,RiskLevel=levels[i],Explanation="latest"});}await db.SaveChangesAsync();var config=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"Pagination:MaxPageSize","100"}}).Build();return new(connection,db,new(db,config),versioned);}
  public async ValueTask DisposeAsync(){await Db.DisposeAsync();await connection.DisposeAsync();}
}
sealed class FakeBatchPipeline:IBatchOperationPipeline {public HashSet<Guid> Fail{get;}=[];public List<Guid> Calls{get;}=[];public Func<Task>? AfterFirst{get;set;}public async Task<BatchOperationExecutionResult> ExecuteAsync(Guid operationId,Guid userId,CancellationToken ct=default){Calls.Add(operationId);if(Calls.Count==1&&AfterFirst is not null)await AfterFirst();return new(null,null,Fail.Contains(operationId)?["Synthetic failure"]:[]);}}
